package com.loyu3c.rental;
import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
final class SyncProtocol {
    static URL endpoint(String value)throws Exception {URL u=new URL(value.trim());if(!u.getProtocol().equals("https")||!u.getHost().equals("script.google.com")||u.getPort()!=-1||u.getUserInfo()!=null||u.getQuery()!=null||u.getRef()!=null||!u.getPath().matches("/macros/s/[a-zA-Z0-9_-]+/exec"))throw new IllegalArgumentException("請填Google Apps Script正式部署網址，結尾為/exec");return u;}
    static URL redirect(String value)throws Exception {URL u=new URL(value);if(!u.getProtocol().equals("https")||!u.getHost().equals("script.googleusercontent.com")||u.getUserInfo()!=null||u.getPort()!=-1)throw new IllegalArgumentException("Google服務要求登入或回應網址不正確，請確認部署存取設定");return u;}
    static void token(String value){if(!value.matches("[a-fA-F0-9]{64}"))throw new IllegalArgumentException("同步金鑰須為Google設定工具產生的64位字元");}
    static String reportUrl(String value){if(!value.matches("https://docs\\.google\\.com/spreadsheets/d/[a-zA-Z0-9_-]+/edit"))throw new IllegalArgumentException("同步服務未回傳有效試算表網址");return value;}
    static String message(String code){switch(code){case "UNAUTHORIZED":return "同步金鑰不正確，請重新設定";case "NOT_CONFIGURED":return "Google端尚未執行初始化設定";case "BUSY":return "Google端正在同步，請稍後重試";case "PERMISSION_FAILED":return "Google分享權限或檔案更新未完成，請檢查部署權限後重試；未確認可查看";case "INVALID_REPORT":return "報表資料或月份不符合Google服務格式";default:return "Google端更新未確認，請核對試算表後重試；不會修改手機帳務";}}
    static JSONObject send(String endpoint,String token,String mode,JSONObject report)throws Exception {
        token(token);String id=java.util.UUID.randomUUID().toString();JSONObject request=new JSONObject().put("version",mode.startsWith("shared")?2:1).put("syncId",id).put("token",token).put("mode",mode);if(report!=null)request.put("report",report);byte[] bytes=request.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>(mode.startsWith("shared")?37000000:1800000))throw new IllegalArgumentException("單次報表過大，請先減少資料範圍");
        HttpURLConnection connection=(HttpURLConnection)endpoint(endpoint).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(20000);connection.setReadTimeout(mode.startsWith("shared")?180000:45000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json; charset=UTF-8");connection.setFixedLengthStreamingMode(bytes.length);
        String body;try {try(OutputStream out=connection.getOutputStream()){out.write(bytes);}int status=connection.getResponseCode();if(status==302||status==303){URL url=redirect(connection.getHeaderField("Location"));connection.disconnect();connection=(HttpURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(20000);connection.setReadTimeout(mode.startsWith("shared")?180000:45000);connection.setRequestMethod("GET");status=connection.getResponseCode();}if(status!=200)throw new IOException("同步服務回應HTTP "+status);try(InputStream in=connection.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);if(out.size()>64000)throw new IOException("Google回應格式不正確");}body=out.toString(StandardCharsets.UTF_8.name());}}finally{connection.disconnect();}
        JSONObject response;try{response=new JSONObject(body);}catch(JSONException e){throw new IOException("Google服務未回傳同步結果，請確認部署為任何人可存取，並由你本人執行");}if(!response.optBoolean("ok"))throw new IOException(message(response.optString("code")));if(!id.equals(response.optString("syncId")))throw new IOException("同步回應不符合本次請求，請重試");if(mode.equals("sharedCheck")){if(!response.optString("capability").equals("audience-v2"))throw new IOException("請更新 Google 部署為多房東版本");return response;}
        if(mode.startsWith("shared")){if(!response.optString("audience").equals(report.getString("audience"))||!response.optString("subjectId").equals(report.getString("subjectId")))throw new IOException("分享回應對象不符");if(mode.equals("sharedSync")){reportUrl(response.getString("url"));if(!response.optString("status").equals("shared")||!response.optString("email").equalsIgnoreCase(report.getString("email")))throw new IOException("分享權限尚未確認");}else if(!response.optString("status").equals("revoked"))throw new IOException("停止分享尚未確認");return response;}
        reportUrl(response.getString("url"));if(mode.equals("sync")&&(!report.getString("month").equals(response.optString("month"))||!response.optString("syncedAt").matches("20[0-9TZ:.+-]{18,40}")))throw new IOException("Google服務未確認報表月份及成功時間");return response;
    }
}

